inputs = ['uxhvcu', 'vbjfhy', 'ku', 'xvedva', 'gxi']
outputs = ['ubhvcu', 'vcazufhy', 'ku', 'yfcedva', 'zbi']

for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Input {i}: '{inp}' -> Output {i}: '{out}'")
    # Show character-by-character differences
    for j, (char_in, char_out) in enumerate(zip(inp, out)):
        if char_in != char_out:
            print(f"  Position {j}: '{char_in}' -> '{char_out}'")
    # For cases where lengths differ
    if len(inp) != len(out):
        print(f"  Length changed: {len(inp)} -> {len(out)}")
    print()

