# Let me think about possible replacement sequences
# I'll consider that each replacement operation can only replace 1-3 characters with 0-3 characters
# So I should look for a series of operations that can transform all inputs

inputs = ['uxhvcu', 'vbjfhy', 'ku', 'xvedva', 'gxi']
outputs = ['ubhvcu', 'vcazufhy', 'ku', 'yfcedva', 'zbi']

# First, let me see if there are obvious one-character replacements
print("One-character replacements:")
replacements = []

# Check for common patterns
patterns = {}
for inp, out in zip(inputs, outputs):
    for i, (char_in, char_out) in enumerate(zip(inp, out)):
        if char_in != char_out:
            if (char_in, char_out) not in patterns:
                patterns[(char_in, char_out)] = []
            patterns[(char_in, char_out)].append((inp, out))

# Look for replacements that appear consistently
for (char_in, char_out), occurrences in patterns.items():
    print(f"'{char_in}' -> '{char_out}': appears in {len(occurrences)} cases")

# Also check if we can find multi-character patterns
print("\nMulti-character patterns:")
for inp, out in zip(inputs, outputs):
    if len(inp) != len(out):
        print(f"'{inp}' -> '{out}' (length change: {len(inp)} -> {len(out)})")

